const face = (family: string, weight: 400 | 700, data: string) =>
  `@font-face{font-family:"${family}";src:url("data:font/woff2;base64,${data}") format("woff2");font-style:normal;font-weight:${weight};font-display:swap;}`;

export const knaufFontCss = [
  face('Knauf Screen', 400, screenRegular),
  face('Knauf Screen', 700, screenBold),
  face('Knauf Screen Head', 400, screenHeadRegular),
  face('Knauf Screen Head', 700, screenHeadBold),
  ':root{--knauf-font-body:"Knauf Screen",Arial,Helvetica,sans-serif;--knauf-font-heading:"Knauf Screen Head","Knauf Screen",Arial,Helvetica,sans-serif;}',
  'html,body,#root{font-family:var(--knauf-font-body);}',
  'h1,h2,h3,h4,h5,h6{font-family:var(--knauf-font-heading);}',
  'button,input,select,textarea{font:inherit;}',
].join('\n');
